export function Workbench() {
  const { S } = useS(); const nav = useNavigate();
  const c = (f: (d: Drama) => boolean) => S.dramas.filter(f).length;
  const todos = [['待分派', c((d) => d.status === '待分派'), '/o/review', '#d46b08'], ['待审核/审核中', c((d) => ['待审核', '审核中'].includes(d.status) && d.reviewer === S.opsUser), '/o/review', '#1668dc'], ['待配置分成', c((d) => d.status === '分成配置中'), '/o/share', '#7c4dff'], ['分成待复核', c((d) => d.status === '分成待复核'), '/o/share?tab=review', '#7c4dff'], ['待对接平台', c((d) => d.status === '审核通过'), '/o/distribution', '#18864b'], ['截图待归档', S.shots.filter((s) => s.status === '待归档').length, '/o/watermark?tab=pending', '#d6153c'], ['结算待录入', S.settles.filter((s) => s.status === '待录入').length, '/o/settle', '#d46b08'], ['结算待复核', S.settles.filter((s) => s.status === '待复核').length, '/o/settle-review', '#1668dc']];
  const role = OPS_USERS.find((u) => u.id === S.opsUser)!.role; const okP = (to: string) => (S.perms[role] || []).includes(to.split('?')[0]);
  const sla = S.dramas.filter((d) => ['待审核', '审核中'].includes(d.status)).sort((a, b) => a.sla - b.sla).slice(0, 8);
  return <div className="page"><PH title={`早上好，${uname(S.opsUser)}`} sub="今天要处理的事都在这里，点卡片直达" />
    <div className="todos">{todos.filter((t: any) => okP(t[2])).map(([k, n, to, col]: any) => <div key={k} className="card todo" onClick={() => nav(to)} style={{ borderTop: `3px solid ${col}` }}><div className="meta">{k}</div><div style={{ fontSize: 30, fontWeight: 700, color: col }}>{n.toLocaleString()}</div></div>)}</div>
    <Row gutter={16} style={{ marginTop: 16 }}>
      <Col span={14}><div className="card"><div className="ct">SLA 即将超时 / 已超时 <a onClick={() => nav('/o/review')}>审核队列 →</a></div>
        <Table size="small" rowKey="id" pagination={false} dataSource={sla} onRow={(r) => ({ onClick: () => nav('/o/review/' + r.id), style: { cursor: 'pointer' } })} columns={[{ title: '剧', render: (d: Drama) => <Space><Cover d={d} h={36} w={27} ep={false} />{d.cn}</Space> }, { title: '客户', render: (d: Drama) => <span className="ell" style={{ maxWidth: 140, display: 'inline-block' }}>{cname(S, d.cust)}</span> }, { title: '处理人', render: (d: Drama) => uname(d.reviewer) }, { title: 'SLA', render: (d: Drama) => <SLA h={d.sla} /> }]} /></div></Col>
      <Col span={10}><div className="card"><div className="ct">今日数据同步（数据日 10/20）<span className="meta">截止 明日 06:00</span></div>
        {PLATFORMS.map((p, i) => { const st = S.syncs.find((x) => x.plat === p.key)?.status || (i < 2 ? '已发布' : i === 2 ? '待人工处理' : '待同步'); return <div key={p.key} style={{ display: 'flex', gap: 10, alignItems: 'center', marginBottom: 12 }}><PlatLogo k={p.key} /><span style={{ width: 90 }}>{p.key}</span><Progress style={{ flex: 1 }} percent={st === '已发布' ? 100 : st === '待人工处理' ? 70 : 0} size="small" strokeColor={p.color} /><ST s={st} /></div>; })}
        <Button block onClick={() => nav('/o/sync')}>去导入报表</Button></div>
        <div className="card" style={{ marginTop: 16 }}><div className="ct">我发起的任务</div><TaskList side="o" /></div></Col></Row></div>;
}

export function Customers() {
  const { S, up, addTask } = useS(); const { message } = App.useApp(); const [sp] = useSearchParams(); const [tab, setTab] = useState(sp.get('tab') || 'cust'); const [q, setQ] = useState(sp.get('q') || ''); const [sel, setSel] = useState<string[]>([]); const [cur, setCur] = useState<any>(null); const [rej, setRej] = useState(''); const [cert, setCert] = useState('全部'); const [lrej, setLrej] = useState<any>(null); const [lwhy, setLwhy] = useState<string>();
  const list = S.customers.filter((c) => (!q || c.name.includes(q) || c.id.includes(q)) && (cert === '全部' || c.cert === cert));
  const lics = [...S.licenses.map((l: any) => ({ ...l, cust: ME, mine: true })), ...S.otherLics]; const lpend = lics.filter((l) => l.status === '审核中').length;
  const setCertSt = (id: string, st: string, reason = '') => { up((n) => { n.customers = n.customers.map((c) => c.id === id ? { ...c, cert: st } : c); if (id === ME) { n.cert = st; n.certInfo = { ...(n.certInfo || {}), reason }; n.notifs = [{ t: now().slice(5), m: st === '已认证' ? '企业认证已通过，现在可以绑定收款账户、申请合同和提款了' : '企业认证未通过：' + reason, to: '/u/account', read: false }, ...n.notifs]; } else if (n.acctStore[id]) { n.acctStore = { ...n.acctStore, [id]: { ...n.acctStore[id], cert: st, notifs: [{ t: now().slice(5), m: st === '已认证' ? '企业认证已通过' : '企业认证未通过：' + reason, to: '/u/account', read: false }, ...n.acctStore[id].notifs] } }; } }); setCur(null); setRej(''); message.success('已' + (st === '已认证' ? '通过' : '驳回') + '，已通知客户'); };
  const setLic = (l: any, st: string, reason = '') => { up((n) => { if (l.mine) { n.licenses = n.licenses.map((x) => x.id === l.id ? { ...x, status: st, reason } : x); n.notifs = [{ t: now().slice(5), m: st === '已通过' ? `授权书「${l.name}」审核通过，可以关联到剧了` : `授权书「${l.name}」未通过：${reason}`, to: '/u/account', read: false }, ...n.notifs]; } else n.otherLics = n.otherLics.map((x) => x.id === l.id ? { ...x, status: st, reason } : x); }); message.success(st === '已通过' ? '资质已通过，客户可关联到剧并发起发行' : '已驳回，客户会收到原因'); };
  const c0 = cur && S.customers.find((c) => c.id === cur.id); const info = c0?.id === ME ? S.certInfo : null;
  return <div className="page"><PH title="客户与资质" icon={<TeamOutlined />} sub={`${S.customers.length} 个客户 · 企业认证审核、授权书/版权证明审核、责任运营分配`} />
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'cust', label: `客户与认证 (${S.customers.filter((c) => c.cert === '审核中').length} 待审)` }, { key: 'lic', label: <span>资质审核 <b style={{ color: '#d6153c' }}>({lpend})</b></span> }]} />
    {tab === 'lic' && <div className="card" style={{ padding: 8 }}><Table rowKey="id" dataSource={lics} pagination={pager(lics.length)} columns={[{ title: '文件', render: (l: any) => <Space><FileProtectOutlined style={{ fontSize: 22, color: '#D6153C' }} /><div><b>{l.name}</b><div className="meta">{l.id}</div></div></Space> }, { title: '客户', render: (l: any) => cname(S, l.cust) }, { title: '有效期', dataIndex: 'exp' }, { title: '上传时间', render: (l: any) => l.time || '2026-09-12 10:00' }, { title: '状态', dataIndex: 'status', render: (v: string) => <ST s={v} />, filters: ['审核中', '已通过', '已驳回'].map((x) => ({ text: x, value: x })), onFilter: (v: any, r: any) => r.status === v }, { title: '', render: (l: any) => l.status === '审核中' ? <Space><Button size="small" type="primary" icon={<CheckOutlined />} onClick={() => setLic(l, '已通过')}>通过</Button><Button size="small" danger onClick={() => { setLrej(l); setLwhy(undefined); }}>驳回</Button></Space> : <span className="meta">{l.reason || '—'}</span> }]} />
      <Modal open={!!lrej} title={`驳回资质 · ${lrej?.name}`} onCancel={() => setLrej(null)} okButtonProps={{ danger: true, disabled: !lwhy }} onOk={() => { setLic(lrej, '已驳回', lwhy); setLrej(null); }}><Select style={{ width: '100%' }} placeholder="驳回原因（必选）" value={lwhy} onChange={setLwhy} options={['文件不清晰', '授权方与认证主体不一致', '授权已过期', '缺少授权剧目清单', '非原件扫描'].map((x) => ({ value: x, label: x }))} /></Modal></div>}
    {tab === 'cust' && <><Space style={{ marginBottom: 12 }} wrap><Input.Search allowClear defaultValue={q} placeholder="客户名 / 客户 ID" onSearch={setQ} style={{ width: 260 }} /><Segmented value={cert} onChange={(v: any) => setCert(v)} options={['全部', '审核中', '已认证', '未认证', '认证驳回'].map((k) => ({ value: k, label: `${k} ${k === '全部' ? '' : S.customers.filter((c) => c.cert === k).length}` }))} />
      {sel.length > 0 && <Select placeholder={`把 ${sel.length} 个客户分配给…`} style={{ width: 220 }} onChange={(v) => { addTask({ side: 'o', name: `批量分配责任运营 · ${sel.length} 个客户`, total: sel.length, run: () => { up((n) => { n.customers = n.customers.map((c) => sel.includes(c.id) ? { ...c, owner: v } : c); }); setSel([]); return { ok: sel.length }; } }); }} options={REVIEWERS.map((u) => ({ value: u.id, label: u.name }))} />}</Space>
    <div className="card" style={{ padding: 8 }}><Table rowKey="id" size="middle" dataSource={list} pagination={pager(list.length)} rowSelection={{ selectedRowKeys: sel, onChange: (k) => setSel(k as string[]), selections: selAll(list, setSel) }} columns={[{ title: '客户', render: (c: any) => <div><b>{c.name}</b><div className="meta">{c.id} · {c.contact} {c.phone}</div></div>, sorter: (a: any, b: any) => a.name.localeCompare(b.name) }, { title: '认证', dataIndex: 'cert', render: (v: string) => <ST s={v} /> }, { title: '剧集数', dataIndex: 'dramas', sorter: (a: any, b: any) => a.dramas - b.dramas }, { title: '责任运营', dataIndex: 'owner', render: uname, filters: OPS_USERS.map((u) => ({ text: u.name, value: u.id })), onFilter: (v: any, r: any) => r.owner === v }, { title: '入驻', dataIndex: 'joined', sorter: (a: any, b: any) => a.joined.localeCompare(b.joined) }, { title: '', render: (c: any) => <Button size="small" type={['审核中', '变更审核中'].includes(c.cert) ? 'primary' : 'default'} onClick={() => setCur(c)}>{['审核中', '变更审核中'].includes(c.cert) ? '审核认证' : '查看'}</Button> }]} /></div></>}
    <Drawer open={!!c0} width={680} title={c0?.name} onClose={() => setCur(null)}>{c0 && <><Descriptions column={2} items={[{ label: '客户 ID', children: c0.id }, { label: '认证状态', children: <ST s={c0.cert} /> }, { label: '企业名称', children: info?.name || c0.name + '有限公司' }, { label: '信用代码', children: info?.code || '91330106MA2H8XXXX' }, { label: '法人', children: info?.legal || '陈星' }, { label: '联系人', children: info?.contact || c0.phone }, { label: '剧集数', children: c0.dramas }, { label: '责任运营', children: uname(c0.owner) }]} />
      <div className="ct" style={{ marginTop: 16 }}>营业执照 <span className="meta">{info?.licFile || '营业执照.jpg'} · 客户上传原件</span></div><Image src={LicImg(info?.name || c0.name + '有限公司', info?.code || '91330106MA2H8XXXX')} width={300} /><div><Button size="small" type="link" icon={<DownloadOutlined />} onClick={() => download(`${c0.id}_营业执照.csv`, [['营业执照', info?.licFile || '营业执照.jpg']])}>下载原件</Button></div>
      {['审核中', '变更审核中'].includes(c0.cert) && <><div className="ct" style={{ marginTop: 16 }}>核对清单</div>{['企业名称与执照一致', '信用代码校验通过', '执照在有效期内', '法人与执照一致'].map((t) => <div key={t}><Checkbox defaultChecked>{t}</Checkbox></div>)}
        <Select style={{ width: '100%', marginTop: 16 }} placeholder="驳回原因（驳回时必选）" value={rej || undefined} onChange={setRej} options={['营业执照模糊', '企业名称与执照不一致', '执照已过期', '法人信息不符'].map((x) => ({ value: x, label: x }))} />
        <Space style={{ marginTop: 16 }}><Button type="primary" icon={<CheckOutlined />} onClick={() => setCertSt(c0.id, '已认证')}>通过</Button><Button danger icon={<CloseOutlined />} disabled={!rej} onClick={() => setCertSt(c0.id, '认证驳回', rej)}>驳回</Button></Space></>}</>}</Drawer></div>;
}

export function ReviewQueue() {
  const { S, up, addTask } = useS(); const nav = useNavigate(); const { message } = App.useApp(); const [tab, setTab] = useState('mine'); const [today, setToday] = useState(false); const cap = S.assignCfg.cap; const sup = isSup(S); const [q, setQ] = useState(''); const [sel, setSel] = useState<string[]>([]); const [rej, setRej] = useState(false); const [rf] = Form.useForm(); const [round, setRound] = useState('全部');
  const base = S.dramas.filter((d) => ['待分派', '待审核', '审核中'].includes(d.status));
  const list = base.filter((d) => (tab === 'mine' ? d.reviewer === S.opsUser && d.status !== '待分派' : tab === 'unassigned' ? d.status === '待分派' : d.status !== '待分派') && (round === '全部' || d.round === round) && (!today || (d.submitted || '').startsWith('2026-10-21')) && (!q || d.cn.includes(q) || d.id.includes(q) || cname(S, d.cust).includes(q))).sort((a, b) => tab === 'unassigned' ? (b.submitted || '').localeCompare(a.submitted || '') : a.sla - b.sla);
  const cs = useColSet('review'); const rqCols = cs.cols; const batchPass = () => { const ids = [...sel]; const okIds = S.dramas.filter((d) => ids.includes(d.id) && d.checked >= d.sample && d.problems === 0).map((d) => d.id); addTask({ side: 'o', name: `批量通过 · ${ids.length} 部`, total: ids.length, icon: <CheckOutlined />, run: () => { up((n) => { n.dramas = n.dramas.map((d) => okIds.includes(d.id) ? { ...d, status: '分成配置中' } : d); n.tickets = [...okIds.map((id) => { const d = n.dramas.find((x) => x.id === id)!; return { id: 'GD-' + nid().toUpperCase().slice(-5), type: '审核结果', did: id, cust: d.cust, plat: '', title: '全部审核通过', time: now(), status: '待客户查看', msgs: [] }; }), ...n.tickets]; }); return { ok: okIds.length, skip: ids.length - okIds.length, report: ids.map((id) => { const d = S.dramas.find((x) => x.id === id)!; const ok = okIds.includes(id); return { ok, m: `《${d.cn}》${ok ? '已通过' : d.problems ? '有问题集，已跳过' : `抽检未完成（${d.checked}/${d.sample}），已跳过`}` }; }) }; } }); setSel([]); };
  const assign = (who: string) => { if (!sup) { message.warning('分派/改派需运营主管（右上角切换为王敏）'); return; } const room = Math.max(0, cap - load(S, who)); const ids = sel.filter((id) => S.dramas.find((d) => d.id === id)?.reviewer !== who).slice(0, room); const over = sel.length - ids.length; up((n) => { n.dramas = n.dramas.map((d) => ids.includes(d.id) ? { ...d, reviewer: who, status: d.status === '待分派' ? '待审核' : d.status } : d); n.opLog = [{ t: now(), a: `${uname(n.opsUser)} ${tab === 'unassigned' ? '分派' : '改派'} ${ids.length} 部给 ${uname(who)}` }, ...n.opLog]; }); message[over ? 'warning' : 'success'](`已${tab === 'unassigned' ? '分派' : '改派'} ${ids.length} 部给 ${uname(who)}${over ? `；${over} 部超出容量 ${cap}，留在原处` : ''}（留痕）`); setSel([]); };
  return <div className="page"><PH title="审核队列" icon={<AuditOutlined />} sub="抽检制：标准抽检 = 前 3 集 + 最后 2 集 + 中间随机 10%" extra={<Space><Tag color={load(S, S.opsUser) >= cap ? 'red' : 'blue'}>我的在审 {load(S, S.opsUser)} / 容量 {cap}{load(S, S.opsUser) >= cap ? '（已满，新单留在待分派）' : ''}</Tag>{sup && <Button size="small" icon={<ClusterOutlined />} onClick={() => nav('/o/review-cfg')}>分派·抽检·SLA</Button>}</Space>} />
    <Tabs activeKey={tab} onChange={(k) => { setTab(k); setSel([]); }} items={[{ key: 'mine', label: `我的队列 (${base.filter((d) => d.reviewer === S.opsUser && d.status !== '待分派').length})` }, { key: 'team', label: `团队队列 (${base.filter((d) => d.status !== '待分派').length})` }, { key: 'unassigned', label: <span>待分派 <b style={{ color: '#d6153c' }}>({base.filter((d) => d.status === '待分派').length})</b></span> }]} />
    <Space style={{ marginBottom: 12 }} wrap><Input.Search allowClear placeholder="剧名 / 剧 ID / 客户" onSearch={setQ} style={{ width: 260 }} /><Segmented value={round} onChange={(v: any) => setRound(v)} options={['全部', '首发', '二轮']} /><Tag.CheckableTag checked={today} onChange={setToday} style={{ border: '1px solid var(--line)', padding: '2px 10px' }}>今日新进 {base.filter((d) => (d.submitted || '').startsWith('2026-10-21')).length}</Tag.CheckableTag>
      {sel.length > 0 && <><b>已选 {sel.length}</b>{tab !== 'unassigned' && <Button type="primary" icon={<CheckOutlined />} onClick={batchPass}>批量通过</Button>}{tab !== 'unassigned' && <Button danger icon={<CloseOutlined />} onClick={() => setRej(true)}>批量驳回</Button>}{tab !== 'mine' && <Tooltip title={sup ? '' : '仅运营主管可分派/改派'}><Select disabled={!sup} value={null as any} placeholder={tab === 'unassigned' ? '分派给…' : '批量改派给…'} style={{ width: 200 }} onChange={assign} options={REVIEWERS.map((u) => ({ value: u.id, label: `${u.name}（${load(S, u.id)}/${cap}）`, disabled: load(S, u.id) >= cap }))} /></Tooltip>}</>}
      {tab === 'unassigned' && <Tooltip title={sup ? `规则：${S.assignCfg.rule}，单人容量 ${cap}` : '仅运营主管'}><Button disabled={!sup} icon={<UserSwitchOutlined />} onClick={() => { const ids = list.map((d) => d.id); addTask({ side: 'o', name: `按规则自动分派 · ${ids.length} 部`, total: ids.length, run: () => { let ok = 0; const rep: any[] = []; up((n) => { const cnt: Record<string, number> = {}; REVIEWERS.forEach((u) => (cnt[u.id] = n.dramas.filter((d) => d.reviewer === u.id && ['待审核', '审核中'].includes(d.status)).length)); n.dramas = n.dramas.map((d) => { if (!ids.includes(d.id)) return d; const owner = n.customers.find((c) => c.id === d.cust)?.owner; const cand = n.assignCfg.rule === '按客户责任运营' && owner && cnt[owner] < cap ? owner : n.assignCfg.rule !== '按客户责任运营' || !owner ? REVIEWERS.map((u) => u.id).sort((a, b) => cnt[a] - cnt[b])[0] : null; if (!cand || cnt[cand] >= cap) return d; cnt[cand]++; ok++; return { ...d, status: '待审核', reviewer: cand }; }); }); return { ok, skip: ids.length - ok, report: ids.length - ok ? [{ ok: false, m: `${ids.length - ok} 部因负责人已满 ${cap} 部，留在待分派` }] : undefined }; } }); }}>按规则自动分派全部</Button></Tooltip>}</Space>
    <div className="card" style={{ padding: 8 }}><Table rowKey="id" size="middle" title={cs.btn} dataSource={list} pagination={pager(list.length)} rowSelection={{ selectedRowKeys: sel, onChange: (k) => setSel(k as string[]), selections: selAll(list, setSel) }}
      columns={rqCols([{ title: '剧', render: (d: Drama) => <Space style={{ cursor: 'pointer' }} onClick={() => nav('/o/review/' + d.id)}><Cover d={d} h={48} w={36} ep={false} /><div><b>{d.cn}</b><div className="meta">{d.id} · {d.eps} 集</div></div></Space> }, { title: '客户', render: (d: Drama) => <span className="ell" style={{ maxWidth: 150, display: 'inline-block' }}>{cname(S, d.cust)}</span> }, { title: '类型', render: (d: Drama) => <Space size={2}><Tag color={d.round === '首发' ? 'red' : 'purple'}>{d.round}</Tag>{d.resub > 0 && <Tag>第{d.resub + 1}次</Tag>}</Space> }, { title: '状态', dataIndex: 'status', render: (s: string) => <ST s={s} /> }, { title: '抽检进度', render: (d: Drama) => <Tooltip title={`${d.checked}/${d.sample} 集，问题 ${d.problems}`}><Progress percent={Math.round((d.checked / d.sample) * 100)} size="small" style={{ width: 110 }} status={d.problems ? 'exception' : undefined} /></Tooltip> }, { title: '处理人', render: (d: Drama) => uname(d.reviewer) }, { title: 'SLA', dataIndex: 'sla', render: (h: number) => <SLA h={h} />, sorter: (a: Drama, b: Drama) => a.sla - b.sla }, { title: '提交', dataIndex: 'submitted', sorter: (a: Drama, b: Drama) => a.submitted.localeCompare(b.submitted) }, { title: '', render: (d: Drama) => <Button size="small" onClick={() => nav('/o/review/' + d.id)}>{d.status === '待分派' ? '查看' : '审核'}</Button> }])} /></div>
    <Modal open={rej} title={`批量驳回 ${sel.length} 部`} onCancel={() => setRej(false)} onOk={() => rf.submit()} okButtonProps={{ danger: true }} okText="驳回并通知客户" destroyOnClose>
      <Form form={rf} layout="vertical" onFinish={(v) => { const ids = [...sel]; addTask({ side: 'o', name: `批量驳回 · ${ids.length} 部`, total: ids.length, run: () => { up((n) => { n.dramas = n.dramas.map((d) => ids.includes(d.id) ? { ...d, status: '需修改', problems: Math.max(1, d.problems) } : d); n.tickets = [...ids.map((id) => { const d = n.dramas.find((x) => x.id === id)!; return { id: 'GD-' + nid().toUpperCase().slice(-5), type: '审核结果', did: id, cust: d.cust, plat: '', title: '需修改：' + v.r.join(' / '), time: now(), status: '待客户查看', msgs: v.note ? [{ who: '运营', t: now(), m: v.note }] : [], eps: [12] }; }), ...n.tickets]; }); return { ok: ids.length }; } }); setRej(false); setSel([]); }}>
        <Form.Item name="r" label="原因（至少选 1 项）" rules={[{ required: true, message: '请至少选择一个驳回原因' }]}><Checkbox.Group options={REJECT_TPL} /></Form.Item><Form.Item name="note" label="补充说明"><Input.TextArea rows={2} /></Form.Item><Alert type="info" showIcon message="每部剧会生成一张审核结果工单，同批次通知合并为一条" /></Form></Modal></div>;
}

export function ReviewDesk() {
  const { id } = useParams(); const { S, up } = useS(); const nav = useNavigate(); const { message } = App.useApp(); const d = S.dramas.find((x) => x.id === id);
  const cfg = S.assignCfg; const mkSample = (dd: Drama, extra = 0) => { const s = new Set<number>([...Array.from({ length: cfg.head }, (_, i) => i + 1), ...Array.from({ length: cfg.tail }, (_, i) => dd.eps - i)]); const target = Math.min(dd.eps, Math.max(dd.sample, cfg.head + cfg.tail + Math.ceil((dd.eps * cfg.mid) / 100)) + extra); let k = 7; while (s.size < target) { s.add(1 + ((k * 37) % dd.eps)); k++; } return [...s].sort((a, b) => a - b); };
  const [eps, setEps] = useState<number[]>(() => (d ? mkSample(d) : [])); const [res, setRes] = useState<Record<number, any>>(() => { const r: any = {}; if (d) mkSample(d).slice(0, d.checked).forEach((e, i) => (r[e] = i < d.problems ? { ok: false, why: '字幕错位' } : { ok: true })); return r; }); const [cur, setCur] = useState<number>(eps[0]); const [why, setWhy] = useState<string>(); const [mode, setMode] = useState('标准抽检');
  if (!d) return <div className="page"><Result status="404" title="剧不存在" extra={<Button onClick={() => nav('/o/review')}>回审核队列</Button>} /></div>;
  const doneN = eps.filter((e) => res[e]).length; const probs = eps.filter((e) => res[e] && !res[e].ok); const all = doneN === eps.length; const active = ['待审核', '审核中'].includes(d.status);
  const mark = (ok: boolean) => { if (!ok && !why) { message.warning('请先选择问题原因'); return; } const n = { ...res, [cur]: ok ? { ok } : { ok, why } }; setRes(n); setWhy(undefined); if (d.status === '待审核') up((s) => { s.dramas = s.dramas.map((x) => x.id === d.id ? { ...x, status: '审核中' } : x); }); const nx = eps.find((e) => !n[e]); if (nx) setCur(nx);
    up((s) => { s.dramas = s.dramas.map((x) => x.id === d.id ? { ...x, checked: Object.keys(n).length, problems: Object.values(n).filter((v: any) => !v.ok).length, sample: eps.length } : x); }); };
  const finish = (pass: boolean) => { up((s) => { s.dramas = s.dramas.map((x) => x.id === d.id ? { ...x, status: pass ? '分成配置中' : '需修改', problems: probs.length } : x); s.tickets = [{ id: 'GD-' + nid().toUpperCase().slice(-5), type: '审核结果', did: d.id, cust: d.cust, plat: '', title: pass ? `审核通过（${mode}${eps.length}集，其余抽检免审）` : `第${probs.join('、')}集需修改：${[...new Set(probs.map((e) => res[e].why))].join(' / ')}`, time: now(), status: '待客户查看', msgs: [], eps: pass ? undefined : probs }, ...s.tickets]; }); message.success(pass ? '已通过，进入分成配置；已生成审核结果工单' : '已驳回，客户会收到工单'); nav('/o/review'); };
  return <div className="page"><PH title={<Space><Button type="text" onClick={() => nav('/o/review')}>←</Button>{d.cn}</Space>} sub={`${cname(S, d.cust)} · ${d.id} · ${d.eps} 集 · ${d.round}`} extra={<><ST s={d.status} />{active && <SLA h={d.sla} />}</>} />
    <Row gutter={16}><Col span={15}><div className="player" style={{ backgroundImage: `linear-gradient(rgba(0,0,0,.3),rgba(0,0,0,.5)),url(${COVERS[d.img]})` }}><PlayCircleFilled style={{ fontSize: 64 }} /><div className="ptitle">第 {cur} 集</div><div className="bar"><i /></div></div>
      <div className="card" style={{ marginTop: 16 }}>{active ? <Space wrap><b>第 {cur} 集：</b><Button type="primary" icon={<CheckOutlined />} onClick={() => mark(true)}>通过 (A)</Button><Select placeholder="问题原因" value={why} onChange={setWhy} style={{ width: 220 }} options={REJECT_TPL.map((x) => ({ value: x, label: x }))} /><Button danger icon={<CloseOutlined />} onClick={() => mark(false)}>标记问题 (R)</Button><Button icon={<ScissorOutlined />} onClick={() => message.info('已在 00:12 打点批注')}>打点批注</Button></Space> : <Alert type="info" showIcon message={`当前状态「${d.status}」，不在审核环节`} />}</div></Col>
      <Col span={9}><div className="card"><div className="ct">{mode} · {doneN}/{eps.length} 集 <Space><Button size="small" disabled={!active} icon={<ZoomInOutlined />} onClick={() => { const n = mkSample(d, Math.ceil(d.eps * 0.2)); setEps(n); setMode('扩大抽检'); }}>扩大抽检</Button><Button size="small" disabled={!active} icon={<ExpandOutlined />} onClick={() => { setEps(Array.from({ length: d.eps }, (_, i) => i + 1)); setMode('全审'); }}>转全审</Button></Space></div>
        <Progress percent={Math.round((doneN / eps.length) * 100)} status={probs.length ? 'exception' : undefined} />
        <div className="epgrid">{eps.map((e) => <div key={e} className={'ep-cell' + (res[e]?.ok ? ' ok' : res[e] ? ' no' : '') + (e === cur ? ' cur' : '')} onClick={() => setCur(e)}>{e}</div>)}</div>
        <div className="meta" style={{ marginTop: 8 }}>策略：前 {cfg.head} 集 + 后 {cfg.tail} 集 + 中间随机 {cfg.mid}% · 问题 ≥ {cfg.expandAt} 集建议扩大抽检</div>{probs.length >= cfg.expandAt && mode === '标准抽检' && active && <Alert type="warning" showIcon style={{ margin: '8px 0' }} message={`已发现 ${probs.length} 个问题集，按策略建议扩大抽检`} />}<div className="meta" style={{ margin: '12px 0' }}>未抽中的 {d.eps - eps.length} 集随剧通过，记录为「抽检免审」</div>
        {probs.length > 0 && <Alert type="error" showIcon message={`${probs.length} 个问题集：${probs.join('、')}`} style={{ marginBottom: 12 }} />}
        <Space><Button type="primary" disabled={!active || !all || probs.length > 0} onClick={() => finish(true)}>通过整部剧</Button><Button danger disabled={!active || !probs.length} onClick={() => finish(false)}>驳回（生成工单）</Button></Space>
        {active && !all && <div className="meta" style={{ marginTop: 8 }}>还有 {eps.length - doneN} 集未审，审完才能提交</div>}</div></Col></Row></div>;
}

export function ReviewCfg() {
  const { S, up, log } = useS() as any; const { message } = App.useApp(); const sup = isSup(S); const [tab, setTab] = useState('sla'); const [f] = Form.useForm(); const cfg = S.assignCfg; const nav = useNavigate();
  const rows = REVIEWERS.map((u) => { const ds = S.dramas.filter((d: Drama) => d.reviewer === u.id && ['待审核', '审核中'].includes(d.status)); return { id: u.id, name: u.name, n: ds.length, over: ds.filter((d: Drama) => d.sla < 0).length, soon: ds.filter((d: Drama) => d.sla >= 0 && d.sla < S.params.remind).length, avg: ds.length ? Math.round(ds.reduce((a: number, b: Drama) => a + b.sla, 0) / ds.length) : 0 }; });
  const unas = S.dramas.filter((d: Drama) => d.status === '待分派').length; const totOver = rows.reduce((a, b) => a + b.over, 0);
  return <div className="page"><PH title="分派 · 抽检 · SLA" icon={<ClusterOutlined />} sub={sup ? '运营主管配置；保存后对之后的分派和新开审核生效，留痕' : '只读：修改需运营主管（右上角切换为王敏）'} />
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'sla', label: 'SLA 看板' }, { key: 'assign', label: '分派规则' }, { key: 'sample', label: '抽检策略' }]} />
    {tab === 'sla' && <><Row gutter={16} style={{ marginBottom: 16 }}>{[['待分派', unas, '#d46b08'], ['已超时', totOver, '#d6153c'], [`${S.params.remind}h 内到期`, rows.reduce((a, b) => a + b.soon, 0), '#fa8c16'], ['团队在审', rows.reduce((a, b) => a + b.n, 0), '#1668dc']].map(([k, v, c]: any) => <Col span={6} key={k}><div className="card" style={{ borderTop: `3px solid ${c}` }}><div className="meta">{k}</div><div style={{ fontSize: 30, fontWeight: 700, color: c }}>{v}</div></div></Col>)}</Row>
      <Conclusion>{totOver ? `有 ${totOver} 部已超时，${rows.sort((a, b) => b.over - a.over)[0].name} 名下最多，建议改派一部分。` : '目前没有超时，团队负载正常。'}</Conclusion>
      <div className="card" style={{ padding: 8, marginTop: 16 }}><Table rowKey="id" pagination={false} dataSource={rows} columns={[{ title: '审核员', dataIndex: 'name' }, { title: `在审 / 容量 ${cfg.cap}`, render: (r: any) => <Progress percent={Math.round((r.n / cfg.cap) * 100)} format={() => `${r.n}/${cfg.cap}`} status={r.n >= cfg.cap ? 'exception' : 'normal'} style={{ width: 200 }} /> }, { title: '已超时', dataIndex: 'over', render: (v: number) => <b style={{ color: v ? '#d6153c' : undefined }}>{v}</b>, sorter: (a: any, b: any) => a.over - b.over }, { title: `${S.params.remind}h 内到期`, dataIndex: 'soon' }, { title: '平均剩余', render: (r: any) => <SLA h={r.avg} /> }, { title: '', render: () => <Button size="small" onClick={() => nav('/o/review')}>去改派</Button> }]} /></div></>}
    {tab !== 'sla' && <div className="card" style={{ maxWidth: 720 }}><Form form={f} layout="vertical" disabled={!sup} initialValues={cfg} onFinish={(v) => { up((n: any) => { n.assignCfg = { ...n.assignCfg, ...v }; }); log(`审核${tab === 'assign' ? '分派规则' : '抽检策略'}修改：` + JSON.stringify(v)); message.success('已保存，对之后的分派/审核生效'); }}>
      {tab === 'assign' && <><Form.Item name="rule" label="分派规则"><Radio.Group optionType="button" options={['按客户责任运营', '按负载均衡', '轮询']} /></Form.Item><Form.Item name="cap" label="单人在审容量上限（超出留在待分派）"><InputNumber min={1} max={200} addonAfter="部" /></Form.Item><Alert type="info" showIcon message="按客户责任运营：责任运营满额时留在待分派，由主管手动改派" /></>}
      {tab === 'sample' && <><Row gutter={12}><Col span={8}><Form.Item name="head" label="前几集必审"><InputNumber min={0} max={10} addonAfter="集" /></Form.Item></Col><Col span={8}><Form.Item name="tail" label="后几集必审"><InputNumber min={0} max={10} addonAfter="集" /></Form.Item></Col><Col span={8}><Form.Item name="mid" label="中间随机抽"><InputNumber min={0} max={100} addonAfter="%" /></Form.Item></Col></Row>
        <Form.Item name="expandAt" label="问题集达到几集时提示扩大抽检"><InputNumber min={1} max={10} addonAfter="集" /></Form.Item><Form.Item name="newFull" label="新客户首部剧全审" valuePropName="checked"><Switch /></Form.Item></>}
      <Button type="primary" htmlType="submit">保存</Button></Form></div>}</div>;
}
const ModeIllu = ({ m }: any) => <svg width="64" height="36" viewBox="0 0 64 36"><line x1="0" y1="35" x2="64" y2="35" stroke="#ccc" />{m !== '无保底' && <line x1="0" y1="20" x2="64" y2="20" stroke="#fa8c16" strokeDasharray="3 2" />}<polyline fill="none" stroke="#D6153C" strokeWidth="2" points={m === '保底' ? '0,20 32,20 64,20' : m === '超保底' ? '0,20 32,20 64,2' : '0,35 64,6'} /></svg>;
export function Share() {
  const { S, up, addTask } = useS(); const { message } = App.useApp(); const [sp] = useSearchParams(); const [tab, setTab] = useState(sp.get('tab') || 'todo'); const [sel, setSel] = useState<string[]>([]); const [wiz, setWiz] = useState(false); const [tpl, setTpl] = useState('TPL-01'); const [edit, setEdit] = useState<Drama | null>(null); const [rows, setRows] = useState<any[]>([]); const [ret, setRet] = useState(''); const [q, setQ] = useState('');
  const todo = S.dramas.filter((d) => d.status === '分成配置中' && (!q || d.cn.includes(q) || cname(S, d.cust).includes(q))); const rv = S.dramas.filter((d) => d.status === '分成待复核' && (!q || d.cn.includes(q)));
  const T = S.shareTpls.find((t) => t.id === tpl)!;
  const apply = () => { const ids = [...sel]; addTask({ side: 'o', name: `分成模板批量套用 · ${T.name} · ${ids.length} 部`, total: ids.length, icon: <PercentageOutlined />, run: () => { up((n) => { n.dramas = n.dramas.map((d) => ids.includes(d.id) ? { ...d, status: '分成待复核', share: { tpl: T.id + ' v' + T.v, rows: T.rows } } : d); }); return { ok: ids.length }; } }); setWiz(false); setSel([]); };
  const review = (pass: boolean) => { if (!isSup(S)) { message.warning('分成复核需运营主管（右上角头像可切换为王敏）'); return; } if (!pass && !ret) { message.warning('退回须填写原因'); return; } const ids = [...sel]; addTask({ side: 'o', name: `分成${pass ? '批量复核通过' : '批量退回'} · ${ids.length} 部`, total: ids.length, run: () => { up((n) => { n.dramas = n.dramas.map((d) => ids.includes(d.id) ? { ...d, status: pass ? '审核通过' : '分成配置中' } : d); }); return { ok: ids.length }; } }); setSel([]); setRet(''); };
  const dcol = [{ title: '剧', render: (d: Drama) => <Space><Cover d={d} h={44} w={33} ep={false} /><div><b>{d.cn}</b><div className="meta">{d.id}</div></div></Space> }, { title: '客户', render: (d: Drama) => cname(S, d.cust), filters: [...new Set(todo.slice(0, 200).map((d) => d.cust))].slice(0, 20).map((c) => ({ text: cname(S, c), value: c })), onFilter: (v: any, r: any) => r.cust === v }, { title: '轮次', dataIndex: 'round' }, { title: '当前配置', render: (d: Drama) => d.share ? <Tag color="purple">{d.share.tpl}</Tag> : <span className="meta">未配置</span> }];
  return <div className="page"><PH title="分成管理" icon={<PercentageOutlined />} sub="模板批量套用 → 主管批量复核；保底金额仅运营端可见、不参与计算" />
    <Tabs activeKey={tab} onChange={(k) => { setTab(k); setSel([]); }} items={[{ key: 'todo', label: `待配置 (${todo.length})` }, { key: 'review', label: `分成复核 (${rv.length})` }, { key: 'tpl', label: '分成模板' }]} />
    {tab !== 'tpl' && <Space style={{ marginBottom: 12 }} wrap><Input.Search allowClear placeholder="剧名 / 客户" onSearch={setQ} style={{ width: 240 }} />{sel.length > 0 && <b>已选 {sel.length}</b>}
      {tab === 'todo' && <Button type="primary" disabled={!sel.length} onClick={() => setWiz(true)}>批量套用模板</Button>}
      {tab === 'review' && <><Button type="primary" disabled={!sel.length} onClick={() => review(true)}>批量复核通过</Button><Input placeholder="退回原因" value={ret} onChange={(e) => setRet(e.target.value)} style={{ width: 200 }} /><Button danger disabled={!sel.length} onClick={() => review(false)}>批量退回</Button></>}</Space>}
    {tab !== 'tpl' && <div className="card" style={{ padding: 8 }}><Table rowKey="id" size="middle" dataSource={tab === 'todo' ? todo : rv} pagination={pager((tab === 'todo' ? todo : rv).length)} rowSelection={{ selectedRowKeys: sel, onChange: (k) => setSel(k as string[]) }} columns={[...dcol, { title: '', render: (d: Drama) => <Button size="small" onClick={() => { setEdit(d); setRows((d.share?.rows || T.rows).map((r: any) => ({ cur: 'USD', ...r }))); }}>逐剧编辑</Button> }]} /></div>}
    {tab === 'tpl' && <Row gutter={16}>{S.shareTpls.map((t) => <Col span={8} key={t.id}><div className="card"><div className="ct">{t.name}<Tag>v{t.v}</Tag></div>{t.rows.map((r: any) => <div key={r.plat} style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 6 }}><PlatLogo k={r.plat} size={18} /><span style={{ width: 80 }}>{r.plat}</span><ModeIllu m={r.mode} /><Tag>{r.mode}</Tag><b>{r.ratio}%{r.ratio2 ? '/' + r.ratio2 + '%' : ''}</b></div>)}</div></Col>)}
      <Col span={24}><div className="card" style={{ marginTop: 16 }}><Space size={32}>{['保底', '超保底', '无保底'].map((m) => <Space key={m}><ModeIllu m={m} /><div><b>{m}</b><div className="meta">{m === '保底' ? '期内不超保底按保底结' : m === '超保底' ? '超出部分按另一比例分' : '纯按收益分成'}</div></div></Space>)}</Space></div></Col></Row>}
    <Modal open={wiz} width={760} title={`批量套用模板 · ${sel.length} 部`} onCancel={() => setWiz(false)} onOk={apply} okText="提交（异步执行）">
      <Radio.Group value={tpl} onChange={(e) => setTpl(e.target.value)} style={{ display: 'flex', gap: 12, marginBottom: 16 }}>{S.shareTpls.map((t) => <Radio.Button key={t.id} value={t.id}>{t.name} v{t.v}</Radio.Button>)}</Radio.Group>
      <div className="ct">差异预览</div><Space size={24} style={{ marginBottom: 12 }}><span className="bignum ok">新配置 {S.dramas.filter((d) => sel.includes(d.id) && !d.share).length}</span><span className="bignum warn">覆盖已有 {S.dramas.filter((d) => sel.includes(d.id) && d.share).length}</span><span className="bignum">跳过 0</span></Space>
      <Table size="small" pagination={{ pageSize: 5 }} rowKey="id" dataSource={S.dramas.filter((d) => sel.includes(d.id))} columns={[{ title: '剧', dataIndex: 'cn' }, { title: '变更', render: (d: Drama) => d.share ? <span>{d.share.tpl} → <b>{T.id} v{T.v}</b></span> : <span>无 → <b>{T.id} v{T.v}</b></span> }]} /><Alert type="info" showIcon message="保底金额套用后需逐剧补填；提交后进入「分成待复核」" /></Modal>
    <Drawer open={!!edit} width={720} title={'分成配置 · ' + edit?.cn} onClose={() => setEdit(null)} extra={<Button type="primary" onClick={() => { const bad = rows.find((r) => r.ratio == null || r.ratio < 0 || r.ratio > 100 || (r.mode !== '无保底' && (!r.min || !r.period))); if (bad) { message.error(`${bad.plat}：比例须在 0-100，保底模式需填保底金额与保底期`); return; } up((n) => { n.dramas = n.dramas.map((d) => d.id === edit!.id ? { ...d, share: { tpl: '手工', rows }, status: '分成待复核' } : d); }); setEdit(null); message.success('已提交复核'); }}>提交复核</Button>}>
      {rows.map((r, i) => { const set = (k: string, v: any) => setRows(rows.map((x, j) => j === i ? { ...x, [k]: v } : x)); return <div key={r.plat} className="sharerow"><Space><PlatLogo k={r.plat} />{r.plat}</Space><Segmented size="small" value={r.mode} onChange={(v) => set('mode', v)} options={['保底', '超保底', '无保底'].map((m) => ({ value: m, label: <div style={{ padding: '2px 0' }}><ModeIllu m={m} /><div style={{ fontSize: 11, lineHeight: 1 }}>{m}</div></div> }))} />
        <InputNumber addonAfter="%" status={r.ratio > 100 || r.ratio < 0 ? 'error' : undefined} value={r.ratio} onChange={(v) => set('ratio', v)} style={{ width: 110 }} />
        {r.mode !== '无保底' && <><Space.Compact><Select value={r.cur} onChange={(v) => set('cur', v)} style={{ width: 80 }} options={['USD', 'EUR', 'CNY'].map((x) => ({ value: x, label: x }))} /><InputNumber placeholder="保底金额" value={r.min} onChange={(v) => set('min', v)} style={{ width: 120 }} /></Space.Compact><DatePicker.RangePicker size="small" placeholder={['保底期起', '止']} onChange={(v) => set('period', v)} style={{ width: 220 }} /></>}
        {r.mode === '超保底' && <InputNumber addonBefore="超出" addonAfter="%" value={r.ratio2} onChange={(v) => set('ratio2', v)} style={{ width: 150 }} />}
        {(r.ratio > 100 || r.ratio < 0) && <span style={{ color: '#d6153c', fontSize: 12 }}>比例须在 0~100</span>}</div>; })}</Drawer></div>;
}

const PSTEPS = ['待对接', '对接中', '待上架', '已上架'];
export function Distribution() {
  const { S, up, addTask } = useS(); const { message } = App.useApp(); const [sp] = useSearchParams(); const [q, setQ] = useState(sp.get('q') || ''); const [st, setSt] = useState('全部'); const [sel, setSel] = useState<string[]>([]); const [link, setLink] = useState<any>(null); const [lf] = Form.useForm(); const [pset, setPset] = useState('首发'); const cols5 = pset === '首发' ? PLATFORMS : pset === '二轮' ? SECOND_PLATS : [...PLATFORMS, ...SECOND_PLATS];
  const list = S.dramas.filter((d) => ['审核通过', '发行对接中', '发行中'].includes(d.status) && (st === '全部' || d.status === st) && (!q || d.cn.includes(q) || d.id.includes(q) || d.cust === q || cname(S, d.cust).includes(q)));
  const setP = (did: string, plat: string, v: string, extra: any = {}) => up((n) => { const dd = n.dramas.find((x) => x.id === did); if (dd?.cust === ME && v === '已上架') n.notifs = [{ t: now().slice(5), m: `《${dd.cn}》已在 ${plat} 上架`, to: '/u/drama/' + did + '?tab=plat', read: false }, ...n.notifs]; n.dramas = n.dramas.map((d) => { if (d.id !== did) return d; const plats = { ...d.plats, [plat]: v }; const live = Object.values(plats).includes('已上架'); return { ...d, plats, ...extra, status: live ? '发行中' : d.status === '审核通过' ? '发行对接中' : d.status }; }); });
  const cell = (d: Drama, k: string) => { const v = d.plats[k]; if (!v) return <span className="meta">—</span>; const col = tagColor(v);
    const next = v === '待对接' ? ['对接中'] : v === '对接中' ? ['待上架', '平台已拒绝'] : v === '待上架' ? ['已上架'] : v === '已上架' ? ['已下架'] : [];
    return <Popover trigger="click" title={`${d.cn} × ${k}`} content={next.length ? <Space direction="vertical">{next.map((x) => <Button key={x} block size="small" danger={x === '平台已拒绝' || x === '已下架'} onClick={() => (x === '已上架' ? setLink({ d, k }) : setP(d.id, k, x))}>→ {x}</Button>)}</Space> : <span className="meta">终态</span>}>
      <span className={'mcell ' + col}>{v}</span></Popover>; };
  return <div className="page"><PH title="发行管理" icon={<ProjectOutlined />} sub="剧 × 平台发行状态看板 · 点格子推进状态" extra={<><Upload showUploadList={false} beforeUpload={() => { const cand = S.dramas.filter((d) => Object.values(d.plats).includes('待上架')).slice(0, 40); addTask({ side: 'o', name: `上架结果批量导入 · ${cand.length} 行`, total: cand.length, icon: <FileExcelOutlined />, run: () => { up((n) => { const ids = new Set(cand.map((c) => c.id)); n.dramas = n.dramas.map((d) => { if (!ids.has(d.id)) return d; const plats = { ...d.plats }; Object.keys(plats).forEach((k) => plats[k] === '待上架' && (plats[k] = '已上架')); return { ...d, plats, status: '发行中' }; }); }); return { ok: cand.length - 2, fail: 2, report: [{ ok: false, m: '第 7 行：平台剧 ID 为空' }, { ok: false, m: '第 19 行：剧 ID 不存在' }] }; } }); return false; }}><Button icon={<FileExcelOutlined />}>Excel 批量录入上架结果</Button></Upload><Button icon={<DownloadOutlined />} onClick={() => download('上架结果模板.csv', [['剧ID', '平台', '平台剧ID', '上架时间', '链接']])}>模板</Button></>} />
    <div className="stcards" style={{ gridTemplateColumns: 'repeat(4,1fr)' }}>{['全部', '审核通过', '发行对接中', '发行中'].map((k) => <div key={k} className={'stcard' + (st === k ? ' on' : '')} onClick={() => setSt(k)}><div><div className="n">{k === '全部' ? S.dramas.filter((d) => ['审核通过', '发行对接中', '发行中'].includes(d.status)).length : S.dramas.filter((d) => d.status === k).length}</div><div className="l">{k === '审核通过' ? '待选平台发行' : k}</div></div></div>)}</div>
    <Space style={{ marginBottom: 12 }}><Input.Search allowClear defaultValue={q} placeholder="剧名 / 剧 ID" onSearch={setQ} style={{ width: 240 }} /><Segmented value={pset} onChange={(v: any) => setPset(v)} options={[{ value: '首发', label: `首发 ${PLATFORMS.length} 家` }, { value: '二轮', label: `二轮 ${SECOND_PLATS.length} 家` }, { value: '全部', label: '全部平台' }]} />{sel.length > 0 && <><b>已选 {sel.length}</b><Button type="primary" onClick={() => { up((n) => { n.dramas = n.dramas.map((d) => { if (!sel.includes(d.id)) return d; const plats = { ...d.plats }; PLATFORMS.forEach((p) => { if (!plats[p.key]) plats[p.key] = '待对接'; if (plats[p.key] === '待对接') plats[p.key] = '对接中'; }); return { ...d, plats, status: d.status === '审核通过' ? '发行对接中' : d.status }; }); }); message.success(`已对 ${sel.length} 部发起平台对接`); setSel([]); }}>选平台发行 / 批量发起对接</Button></>}</Space>
    <div className="card" style={{ padding: 8 }}><Table rowKey="id" size="small" dataSource={list} pagination={pager(list.length)} scroll={{ x: 560 + cols5.length * 120 }} rowSelection={{ selectedRowKeys: sel, onChange: (k) => setSel(k as string[]), selections: selAll(list, setSel), fixed: true }} columns={[{ title: '剧', fixed: 'left', width: 260, render: (d: Drama) => <Space><Cover d={d} h={40} w={30} ep={false} /><div><b className="ell" style={{ display: 'block', maxWidth: 200 }}>{d.cn}</b><div className="meta">{d.id}</div></div></Space> }, { title: '客户', width: 170, render: (d: Drama) => <span className="ell" style={{ maxWidth: 160, display: 'inline-block' }}>{cname(S, d.cust)}</span> }, { title: '状态', width: 110, render: (d: Drama) => <ST s={d.status} /> }, ...cols5.map((p) => ({ width: 120, title: <Space size={4}><PlatLogo k={p.key} size={18} />{p.key}</Space>, render: (d: Drama) => cell(d, p.key) }))]} /></div>
    <Modal open={!!link} title={`录入上架信息 · ${link?.k}`} onCancel={() => setLink(null)} onOk={() => lf.submit()} destroyOnClose><Form form={lf} layout="vertical" onFinish={(v) => { setP(link.d.id, link.k, '已上架'); setLink(null); message.success('已上架，记得补防伪截图'); }}>
      <Form.Item name="pid" label="平台剧 ID" rules={[{ required: true, message: '必填' }]}><Input /></Form.Item><Form.Item name="url" label="上架链接" rules={[{ required: true, type: 'url', message: '请输入有效链接' }]}><Input prefix={<LinkOutlined />} placeholder="https://" /></Form.Item><Form.Item name="t" label="上架时间"><DatePicker showTime style={{ width: '100%' }} /></Form.Item></Form></Modal></div>;
}

// ───────── 数据同步 + 报表一键导入
const FIELDS = ['平台剧ID', '剧名', '日期', '播放量', '完播率', '解锁数', '收入', '币种', '（忽略）'];
const SRC_COLS = [['series_id', '平台剧ID'], ['title', '剧名'], ['stat_date', '日期'], ['views', '播放量'], ['completion', '完播率'], ['unlocks', '解锁数'], ['revenue_usd', ''], ['region', '（忽略）']];
export function Sync() {
  const { S, up } = useS(); const { message } = App.useApp(); const [imp, setImp] = useState<string | null>(null); const [tab, setTab] = useState('board'); const [fixes, setFixes] = useState<any[]>([{ id: 'XZ-001', plat: 'FlexTV', date: '2026-10-09', did: 'D10003', field: '播放量', from: 41200, to: 132800, why: '平台补发数据（客户工单 GD-10240）', by: '林晓', status: '待审批' }]); const [nf, setNf] = useState(false); const [ff] = Form.useForm();
  const rows = PLATFORMS.flatMap((p, i) => [0, 1].map((k) => { const date = `2026-10-${p.sync === 'T-1' ? 20 - k : 19 - k}`; const s = S.syncs.find((x) => x.plat === p.key && x.date === date); return { k: p.key + date, plat: p.key, date, way: p.api, status: s?.status || (k === 1 ? '已发布' : i < 2 ? '已发布' : i === 2 ? '待人工处理' : '待同步'), rows: s?.rows || (k === 1 || i < 2 ? 1200 + i * 87 : 0), ver: s?.ver || 1 }; }));
  return <div className="page"><PH title="数据同步 / 报表导入" icon={<ImportOutlined />} sub="平台 × 数据日期 · 每日 06:00 截止 · 导入替代逐条手填" extra={<Statistic.Countdown title="距今日截止（演示）" value={Date.now() + 15 * 3600e3 + 5 * 60e3} format="HH:mm:ss" valueStyle={{ fontSize: 20 }} />} />
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'board', label: '同步任务看板' }, { key: 'fix', label: `数据修正 (${fixes.filter((f) => f.status === '待审批').length})` }, { key: 'api', label: '接口调研登记' }]} />
    {tab === 'fix' && <div className="card" style={{ padding: 8 }}><div style={{ padding: 8, textAlign: 'right' }}><Button type="primary" icon={<PlusOutlined />} onClick={() => setNf(true)}>发起数据修正</Button></div><Table rowKey="id" pagination={pager(fixes.length)} dataSource={fixes} columns={[{ title: '单号', dataIndex: 'id' }, { title: '平台', dataIndex: 'plat' }, { title: '数据日期', dataIndex: 'date' }, { title: '剧', render: (f: any) => S.dramas.find((d) => d.id === f.did)?.cn }, { title: '字段', dataIndex: 'field' }, { title: '修改前 → 后', render: (f: any) => <span>{f.from.toLocaleString()} → <b>{f.to.toLocaleString()}</b></span> }, { title: '原因', dataIndex: 'why', ellipsis: true }, { title: '发起人', dataIndex: 'by' }, { title: '状态', dataIndex: 'status', render: (s: string) => <ST s={s === '待审批' ? '待复核' : s === '已生效' ? '已发布' : '已退回'} /> }, { title: '', render: (f: any) => f.status === '待审批' && <Space><Button size="small" type="primary" onClick={() => { if (!isSup(S)) { message.warning('数据修正需运营主管审批（右上角切换为王敏）'); return; } setFixes(fixes.map((x) => x.id === f.id ? { ...x, status: '已生效' } : x)); message.success('已审批，生成新版本 v2，旧值进入版本历史'); }}>审批通过</Button><Button size="small" onClick={() => setFixes(fixes.map((x) => x.id === f.id ? { ...x, status: '已驳回' } : x))}>驳回</Button></Space> }]} />
      <Modal open={nf} title="发起数据修正（已发布数据）" onCancel={() => setNf(false)} onOk={() => ff.submit()} destroyOnClose><Form form={ff} layout="vertical" onFinish={(v) => { setFixes([{ id: 'XZ-' + nid().slice(-3), ...v, date: v.date.format('YYYY-MM-DD'), from: 52000, by: uname(S.opsUser), status: '待审批' }, ...fixes]); setNf(false); }}><Row gutter={12}><Col span={12}><Form.Item name="plat" label="平台" rules={[{ required: true }]}><Select options={PLATFORMS.map((p) => ({ value: p.key, label: p.key }))} /></Form.Item></Col><Col span={12}><Form.Item name="date" label="数据日期" rules={[{ required: true }]}><DatePicker style={{ width: '100%' }} /></Form.Item></Col></Row><Form.Item name="did" label="剧" rules={[{ required: true }]}><Select showSearch optionFilterProp="label" options={S.dramas.filter((d) => d.status === '发行中').slice(0, 200).map((d) => ({ value: d.id, label: d.cn }))} /></Form.Item><Row gutter={12}><Col span={12}><Form.Item name="field" label="字段" initialValue="播放量"><Select options={['播放量', '收入', '完播率'].map((x) => ({ value: x, label: x }))} /></Form.Item></Col><Col span={12}><Form.Item name="to" label="新值" rules={[{ required: true }]}><InputNumber min={0} style={{ width: '100%' }} /></Form.Item></Col></Row><Form.Item name="why" label="修正原因" rules={[{ required: true, message: '必填' }]}><Input /></Form.Item></Form></Modal></div>}
    {tab === 'api' && <div className="card" style={{ padding: 8 }}><Table rowKey="k" pagination={false} dataSource={PLATFORMS.map((p, i) => ({ k: p.key, plat: p.key, api: ['有开放 API', '仅后台导出', '仅后台导出', '有开放 API', '洽谈中'][i], fields: ['播放/收入/完播', '播放/收入', '播放/收入/解锁', '播放/收入', '—'][i], owner: ['陈宇', '刘洋', '刘洋', '陈宇', '林晓'][i], next: ['已接入', '每日 Excel', '每日 Excel', '已接入', '10/30 再沟通'][i] }))} columns={[{ title: '平台', dataIndex: 'plat', render: (k: string) => <Space><PlatLogo k={k} />{k}</Space> }, { title: '接口能力', dataIndex: 'api' }, { title: '可取字段', dataIndex: 'fields' }, { title: '负责人', dataIndex: 'owner' }, { title: '结论/下一步', dataIndex: 'next' }]} /></div>}
    {tab === 'board' && <div className="card" style={{ padding: 8 }}><Table rowKey="k" dataSource={rows} pagination={false} columns={[{ title: '平台', dataIndex: 'plat', render: (k: string) => <Space><PlatLogo k={k} />{k}</Space> }, { title: '数据日期', dataIndex: 'date' }, { title: '口径', render: (r: any) => PLATFORMS.find((p) => p.key === r.plat)!.sync }, { title: '方式', dataIndex: 'way', render: (v: string) => <Tag>{v === 'API' ? 'API 自动' : '报表导入'}</Tag> }, { title: '状态', dataIndex: 'status', render: (s: string) => <ST s={s} /> }, { title: '行数', dataIndex: 'rows' }, { title: '版本', dataIndex: 'ver', render: (v: number) => 'v' + v }, { title: '', render: (r: any) => r.status === '待主管处理' ? <Tooltip title={isSup(S) ? '' : '等待运营主管处理'}><Button size="small" type="primary" danger disabled={!isSup(S)} onClick={() => setImp(r.plat + '|' + r.date)}>主管处理</Button></Tooltip> : <Button size="small" type={r.status === '已发布' ? 'default' : 'primary'} icon={<ImportOutlined />} onClick={() => setImp(r.plat + '|' + r.date)}>{r.status === '已发布' ? '补充导入' : '导入报表'}</Button> }]} /></div>}
    {imp && <ImportWizard pd={imp} onClose={() => setImp(null)} />}</div>;
}
function ImportWizard({ pd, onClose }: any) {
  const [plat, date] = pd.split('|'); const { S, up, addTask } = useS(); const { message } = App.useApp(); const esc = S.syncs.find((x) => x.plat === plat && x.date === date && x.status === '待主管处理'); const [step, setStep] = useState(esc ? 4 : 0); const [map, setMap] = useState<Record<string, string>>(Object.fromEntries(SRC_COLS.map(([a, b]) => [a, b]))); const [saveTpl, setSaveTpl] = useState(true); const [onlyErr, setOnlyErr] = useState(true);
  const live = S.dramas.filter((d) => d.status === '发行中').slice(0, 1180);
  const [match, setMatch] = useState<any[]>(() => [{ k: 1, raw: 'Hidden Vows (Dub)', cands: live.slice(0, 3), pick: null }, { k: 2, raw: 'The Substitue Bride', cands: live.slice(3, 5), pick: null }, { k: 3, raw: 'Dragon King Returns EP', cands: live.slice(5, 8), pick: null }, { k: 4, raw: 'Unknown Series 8812', cands: [], pick: null }, { k: 5, raw: 'Mommy Run 2', cands: [], pick: null }]);
  const [errs, setErrs] = useState<any[]>(() => [{ k: 'r37', row: 37, d: live[9], f: '播放量', v: -100, why: '负数' }, { k: 'r112', row: 112, d: live[14], f: '收入', v: null, why: '必填为空' }, { k: 'r245', row: 245, d: live[20], f: '播放量', v: 980000, why: '环比 +412%，请确认', warn: true }, { k: 'r601', row: 601, d: live[33], f: '完播率', v: 1.4, why: '超出 0~1' }]);
  const valid = (e: any) => e.v != null && e.v >= 0 && (e.f !== '完播率' || e.v <= 1) && (!e.warn || e.ok);
  const mapOk = Object.values(map).every((v) => v); const matchOk = match.every((m) => m.pick); const errLeft = errs.filter((e) => !valid(e) && !e.ignore).length;
  const publish = (force = false) => { up((n) => { n.syncs = [...n.syncs.filter((x) => !(x.plat === plat && x.date === date)), { plat, date, status: '已发布', rows: 1186 - (force ? errLeft : 0), ver: 2 }]; match.forEach((m) => { if (m.pick && m.pick !== 'ignore') n.aliases[m.raw] = m.pick; }); }); message.success(`${plat} ${date} 已发布，客户端「数据更新到」已刷新`); setStep(5); };
  return <Drawer open width={1100} title={`报表导入 · ${plat} · 数据日期 ${date}`} onClose={onClose}>
    <Steps current={step} size="small" items={['上传', '字段映射', '剧名匹配', '校验与修正', '发布'].map((t) => ({ title: t }))} style={{ marginBottom: 24 }} />
    {step === 0 && <><Upload.Dragger accept=".xlsx,.csv" showUploadList={false} beforeUpload={(f) => { if (S.syncs.find((x) => x.plat === plat && x.date === date)) { Modal.confirm({ title: '这个文件已经导入过', content: '同平台同日期同文件哈希，继续将覆盖并生成新版本。', onOk: () => setStep(1) }); } else setStep(1); return false; }}><p style={{ fontSize: 48, color: '#18864b', margin: 0 }}><FileExcelOutlined /></p><p style={{ fontWeight: 600 }}>拖入 {plat} 后台导出的 Excel / CSV</p><p className="meta">单文件 ≤ 50MB / 20 万行 · 按文件名和表头自动识别平台</p></Upload.Dragger><div style={{ textAlign: 'center', marginTop: 12 }}><Button type="link" onClick={() => setStep(1)}>使用示例报表（1,186 行）</Button></div></>}
    {step === 1 && <><Alert type="warning" showIcon message={`已自动套用「${plat} 映射模板 v2」，表头新增 1 列 revenue_usd 需要确认`} style={{ marginBottom: 16 }} />
      <div className="mapgrid">{SRC_COLS.map(([src]) => <div key={src} className={'maprow' + (!map[src] ? ' need' : '')}><code>{src}</code><span>→</span><Select value={map[src] || undefined} placeholder="选择我方字段" status={!map[src] ? 'error' : undefined} style={{ width: 200 }} onChange={(v) => setMap({ ...map, [src]: v })} options={FIELDS.map((f) => ({ value: f, label: f }))} /></div>)}</div>
      <Checkbox checked={saveTpl} onChange={(e) => setSaveTpl(e.target.checked)} style={{ marginTop: 16 }}>保存为「{plat} 映射模板 v3」</Checkbox></>}
    {step === 2 && <><Space size={24} style={{ marginBottom: 16 }}><span className="bignum ok"><CheckCircleFilled /> 自动匹配 1,181</span><span className="bignum warn"><WarningFilled /> 模糊候选 {match.filter((m) => m.cands.length).length}</span><span className="bignum bad"><CloseCircleFilled /> 未匹配 {match.filter((m) => !m.cands.length).length}</span></Space>
      {match.map((m) => <div key={m.k} className={'matchrow' + (m.pick ? ' done' : '')}><code style={{ width: 220 }}>{m.raw}</code><span>→</span>
        {m.cands.length ? <Radio.Group value={m.pick} onChange={(e) => setMatch(match.map((x) => x.k === m.k ? { ...x, pick: e.target.value } : x))}>{m.cands.map((c: Drama, i: number) => <Radio.Button key={c.id} value={c.id}><Space size={4}><img src={COVERS[c.img]} style={{ width: 16, height: 20, objectFit: 'cover', borderRadius: 2 }} />{c.cn.slice(0, 10)} <span className="meta">{[0.94, 0.89, 0.86][i]}</span></Space></Radio.Button>)}</Radio.Group>
          : <Select showSearch placeholder="搜索指定剧" style={{ width: 260 }} optionFilterProp="label" value={m.pick && m.pick !== 'ignore' ? m.pick : undefined} onChange={(v) => setMatch(match.map((x) => x.k === m.k ? { ...x, pick: v } : x))} options={live.slice(0, 300).map((d) => ({ value: d.id, label: d.cn }))} />}
        <Button size="small" type={m.pick === 'ignore' ? 'primary' : 'default'} onClick={() => setMatch(match.map((x) => x.k === m.k ? { ...x, pick: 'ignore' } : x))}>忽略</Button>{m.pick && <CheckCircleFilled style={{ color: '#18864b' }} />}</div>)}
      <Space style={{ marginTop: 12 }}><Button onClick={() => setMatch(match.map((m) => ({ ...m, pick: m.pick || (m.cands[0]?.id ?? 'ignore') })))}>同名批量确认（取最高相似度，无候选则忽略）</Button><span className="meta">确认结果写入别名库，下次自动命中</span></Space></>}
    {step === 3 && <><Space style={{ marginBottom: 12 }}><Switch checked={onlyErr} onChange={setOnlyErr} /> 只看异常行 <span className="meta">· 共 1,186 行，{errLeft} 行待修正</span></Space>
      <Table size="small" rowKey="k" pagination={false} dataSource={onlyErr ? errs : [...errs, ...live.slice(40, 52).map((d, i) => ({ k: 'ok' + i, row: 700 + i, d, f: '播放量', v: 12000 + i * 97, why: '' }))]} rowClassName={(e: any) => (e.why && !valid(e) && !e.ignore ? 'errrow' : '')}
        columns={[{ title: '行', dataIndex: 'row', width: 60 }, { title: '剧', render: (e: any) => e.d.cn }, { title: '字段', dataIndex: 'f' }, { title: '值（可直接修改）', render: (e: any) => <InputNumber prefix={e.f === '收入' ? 'US$' : undefined} status={e.why && !valid(e) && !e.ignore ? 'error' : undefined} value={e.v} onChange={(v) => setErrs(errs.map((x) => x.k === e.k ? { ...x, v } : x))} style={{ width: 140 }} /> }, { title: '问题', render: (e: any) => e.why ? (valid(e) || e.ignore ? <Tag color="success">已处理</Tag> : <Tag color={e.warn ? 'warning' : 'error'}>{e.why}</Tag>) : <Tag color="success">通过</Tag> }, { title: '', render: (e: any) => e.why && <Space>{e.warn && !e.ok && <Button size="small" onClick={() => setErrs(errs.map((x) => x.k === e.k ? { ...x, ok: true } : x))}>确认无误</Button>}<Button size="small" type="text" onClick={() => setErrs(errs.map((x) => x.k === e.k ? { ...x, ignore: true } : x))}>标记忽略</Button></Space> }]} /></>}
    {step === 4 && <Result status={errLeft ? 'warning' : 'success'} title={errLeft ? `还有 ${errLeft} 行未处理` : '全部通过，可以发布'} subTitle={`总 1,186 行 · 自动匹配 1,181 · 人工确认 ${match.filter((m) => m.pick && m.pick !== 'ignore').length} · 忽略 ${match.filter((m) => m.pick === 'ignore').length + errs.filter((e) => e.ignore).length} · 修正 ${errs.filter((e) => valid(e)).length}`}
      extra={<Space><Button type="primary" size="large" disabled={!!errLeft} onClick={() => publish()}>发布</Button>{errLeft > 0 && isSup(S) && <Button danger onClick={() => publish(true)}>排除问题行强制发布（主管）</Button>}{errLeft > 0 && !isSup(S) && <Button icon={<SendOutlined />} onClick={() => { up((n) => { n.syncs = [...n.syncs.filter((x) => !(x.plat === plat && x.date === date)), { plat, date, status: '待主管处理', rows: 1186, ver: 1, by: uname(n.opsUser), left: errLeft }]; opsNotify(n, `@王敏 ${uname(n.opsUser)} 提交 ${plat} ${date} 报表（${errLeft} 行问题）待主管处理`, '/o/sync'); }); addTask({ side: 'o', name: `${plat} ${date} 报表 · 已提交主管处理（${errLeft} 行问题）`, total: 1, dur: 800, run: () => ({ ok: 1 }) }); message.success('已提交主管处理，主管会在通知和看板里看到'); onClose(); }}>提交主管处理（{errLeft} 行问题）</Button>}</Space>} />}
    {step === 4 && esc && <Alert type="warning" showIcon style={{ marginTop: 12 }} message={`${esc.by} 提交主管处理：${esc.left} 行问题未解决。可逐行修正后发布，或排除问题行强制发布。`} />}
    {step === 5 && <Result status="success" title="已发布" subTitle="结果报告已生成，可下载" extra={<Space><Button icon={<DownloadOutlined />} onClick={() => download(`导入报告_${plat}_${date}.csv`, [['总行数', 1186], ['自动匹配', 1181], ['人工确认', match.length], ['修正', errs.length]])}>下载报告</Button><Button type="primary" onClick={onClose}>完成</Button></Space>} />}
    {step > 0 && step < 5 && <div className="wizfoot"><Button onClick={() => setStep(step - 1)}>上一步</Button>{step < 4 && <Button type="primary" disabled={[true, mapOk, matchOk, true][step] === false} onClick={() => { if (step === 1 && saveTpl) message.success(`已保存 ${plat} 映射模板 v3`); setStep(step + 1); }}>下一步</Button>}</div>}
  </Drawer>;
}

// ───────── 防伪截图
export function Watermark() {
  const { S, up } = useS(); const { message } = App.useApp(); const [sp] = useSearchParams(); const [tab, setTab] = useState(sp.get('tab') || 'single'); const [f] = Form.useForm(); const [shot, setShot] = useState<any>(null); const [sel, setSel] = useState<string[]>([]); const [asg, setAsg] = useState<any>({});
  const live = S.dramas.filter((d) => d.status === '发行中').slice(0, 400);
  const pushTicket = (did: string, plat: string, n = 1) => { const d = S.dramas.find((x) => x.id === did)!; up((s) => { const ex = s.tickets.find((t) => t.type === '防伪截图' && t.cust === d.cust && t.time.startsWith('2026-10-21')); if (ex) s.tickets = s.tickets.map((t) => t === ex ? { ...t, shots: (t.shots || 1) + n, status: '待客户查看' } : t); else s.tickets = [{ id: 'GD-' + nid().toUpperCase().slice(-5), type: '防伪截图', did, cust: d.cust, plat, title: `${plat} 上架截图（今日汇总）`, time: now(), status: '待客户查看', msgs: [], shots: n }, ...s.tickets]; if (d.cust === ME) s.notifs = [{ t: now().slice(5), m: `《${d.cn}》${plat} 上架截图已到`, to: '/u/tickets', read: false }, ...s.notifs]; }); };
  const pend = S.shots.filter((s) => s.status === '待归档');
  return <div className="page"><PH title="防伪截图" icon={<CameraOutlined />} sub="服务端加水印（时间/操作人/工单号/平台/哈希）· 每客户每日合并为一张工单" />
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'single', label: '单张取证' }, { key: 'batch', label: '批量上传' }, { key: 'pending', label: <Badge count={pend.length} size="small" offset={[10, 0]}>待归档</Badge> }, { key: 'done', label: '已归档' }]} />
    {tab === 'single' && <Row gutter={24}><Col span={12}><div className="card"><Form form={f} layout="vertical" onFinish={(v) => setShot({ ...v, t: { id: 'GD-新', time: now() } })}>
      <Form.Item name="did" label="剧" rules={[{ required: true, message: '选择剧' }]}><Select showSearch optionFilterProp="label" options={live.map((d) => ({ value: d.id, label: d.cn + ' · ' + cname(S, d.cust) }))} /></Form.Item>
      <Row gutter={12}><Col span={12}><Form.Item name="plat" label="平台" rules={[{ required: true, message: '选择平台' }]}><Select options={PLATFORMS.map((p) => ({ value: p.key, label: p.key }))} /></Form.Item></Col><Col span={12}><Form.Item name="kind" label="类型" initialValue="上架"><Segmented options={['上架', '数据', '下架']} /></Form.Item></Col></Row>
      <Form.Item label="截图" name="img" rules={[{ required: true, message: '上传截图或网页截屏' }]} valuePropName="fileList" getValueFromEvent={(e) => e.fileList}><Upload.Dragger beforeUpload={() => false} maxCount={1} accept="image/*"><p style={{ fontSize: 36, color: '#D6153C', margin: 0 }}><CameraOutlined /></p><p>拖入截图 / 点击上传</p></Upload.Dragger></Form.Item>
      <Space><Button onClick={() => f.setFieldsValue({ img: [{ uid: '1', name: '网页截屏.png', status: 'done' }] })}>网页内截屏</Button><Button type="primary" htmlType="submit">生成水印图</Button></Space></Form></div></Col>
      <Col span={12}>{shot ? <div className="card"><div className="ct">水印预览（服务器时间）</div><div style={{ width: 240 }}><WMark t={shot.t} d={S.dramas.find((x) => x.id === shot.did)} plat={shot.plat} /></div><Button type="primary" style={{ marginTop: 16 }} onClick={() => { pushTicket(shot.did, shot.plat); up((s) => { s.shots = [{ id: nid('WM'), file: '网页截屏.png', status: '已归档', did: shot.did, plat: shot.plat, date: '2026-10-21' }, ...s.shots]; }); setShot(null); f.resetFields(); message.success('已推送到客户今日截图工单'); }}>推送到工单</Button></div> : <Empty2 title="填写左侧信息生成水印图" desc="原图仅运营可见，水印图推送给客户" />}</Col></Row>}
    {tab === 'batch' && <><Alert type="info" showIcon style={{ marginBottom: 16 }} message="文件名规则：{平台代码}_{剧ID或剧名}_{YYYYMMDD}_{类型}_{序号}.png，例：RS_D10001_20261020_上架_01.png" />
      <Upload.Dragger multiple showUploadList={false} beforeUpload={(file, fl) => { if (file !== fl[0]) return false; const parsed = fl.map((x: any) => { const m = x.name.match(/^(RS|DB|SM|FT|GS)_(D\d+)_(\d{8})_/); const pl = m && PLATFORMS.find((p) => p.short === m[1])?.key; const ok = m && S.dramas.some((d) => d.id === m[2]); return ok ? { id: nid('WM'), file: x.name, status: '已归档', did: m[2], plat: pl, date: m[3] } : { id: nid('WM'), file: x.name, status: '待归档', reason: m ? '剧不存在' : '文件名不符合规则' }; }); up((s) => { s.shots = [...parsed, ...s.shots]; }); parsed.filter((p: any) => p.status === '已归档').forEach((p: any) => pushTicket(p.did, p.plat)); message.success(`${parsed.filter((p: any) => p.status === '已归档').length} 张自动归档，${parsed.filter((p: any) => p.status !== '已归档').length} 张进入待归档`); return false; }}>
        <p style={{ fontSize: 48, color: '#D6153C', margin: 0 }}><InboxOutlined /></p><p style={{ fontWeight: 600 }}>拖入多张截图或 zip（≤500 张）</p></Upload.Dragger>
      <div style={{ textAlign: 'center', marginTop: 12 }}><Button type="link" onClick={() => { const demo = [{ id: nid('WM'), file: 'RS_D10002_20261020_上架_01.png', status: '已归档', did: 'D10002', plat: 'ReelShort', date: '20261020' }, { id: nid('WM'), file: 'GS_D10003_20261020_数据_02.png', status: '已归档', did: 'D10003', plat: 'GoodShort', date: '20261020' }, { id: nid('WM'), file: 'Screenshot 2026-10-20.png', status: '待归档', reason: '文件名不符合规则' }, { id: nid('WM'), file: 'FT_龙王殿_20261020_上架_01.png', status: '待归档', reason: '剧名多候选', cands: ['D10003', 'D10021'] }]; up((s) => { s.shots = [...demo, ...s.shots]; }); pushTicket('D10002', 'ReelShort'); pushTicket('D10003', 'GoodShort'); message.success('2 张自动归档，2 张进入待归档'); }}>用 4 张示例截图体验</Button></div></>}
    {tab === 'pending' && (pend.length ? <><Space style={{ marginBottom: 12 }} wrap><b>已选 {sel.length}</b><Select showSearch optionFilterProp="label" placeholder="指定剧" style={{ width: 240 }} onChange={(v) => setAsg({ ...asg, did: v })} options={live.slice(0, 200).map((d) => ({ value: d.id, label: d.cn }))} /><Select placeholder="平台" style={{ width: 140 }} onChange={(v) => setAsg({ ...asg, plat: v })} options={PLATFORMS.map((p) => ({ value: p.key, label: p.key }))} /><DatePicker onChange={(v) => setAsg({ ...asg, date: v?.format('YYYYMMDD') })} />
      <Button type="primary" disabled={!sel.length || !asg.did || !asg.plat} onClick={() => { up((s) => { s.shots = s.shots.map((x) => sel.includes(x.id) ? { ...x, status: '已归档', did: asg.did, plat: asg.plat, date: asg.date || '20261020' } : x); }); pushTicket(asg.did, asg.plat, sel.length); message.success(`${sel.length} 张已归档（留痕）`); setSel([]); }}>批量归档</Button></Space>
      <div className="shotwall">{pend.map((s, i) => <div key={s.id} className={'shot' + (sel.includes(s.id) ? ' on' : '')} onClick={() => setSel(sel.includes(s.id) ? sel.filter((x) => x !== s.id) : [...sel, s.id])}><div className="sthumb" style={{ backgroundImage: `url(${COVERS[i % 6]})` }}><Checkbox checked={sel.includes(s.id)} className="ck2" /></div><div className="ell" style={{ fontSize: 12 }}>{s.file}</div><Tag color="warning">{s.reason}</Tag>{s.cands && <div className="meta">候选：{s.cands.join(' / ')}</div>}</div>)}</div></> : <Empty2 title="没有待归档截图" desc="全部自动归档了 🎉" />)}
    {tab === 'done' && <div className="card" style={{ padding: 8 }}><Table rowKey="id" size="small" dataSource={S.shots.filter((s) => s.status === '已归档')} pagination={pager(S.shots.length)} columns={[{ title: '文件', dataIndex: 'file' }, { title: '剧', render: (s: any) => S.dramas.find((d) => d.id === s.did)?.cn }, { title: '平台', dataIndex: 'plat' }, { title: '日期', dataIndex: 'date' }, { title: '状态', render: () => <ST s="已归档" /> }]} /></div>}</div>;
}
